use std::sync::{Arc,Barrier};use std::time::{SystemTime,UNIX_EPOCH};fn main(){let mut duplicate_batches=0;for _ in 0..1000{let barrier=Arc::new(Barrier::new(6));let handles:Vec<_>=(0..6).map(|_|{let b=barrier.clone();std::thread::spawn(move||{b.wait();SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()})}).collect();let mut times:Vec<_>=handles.into_iter().map(|h|h.join().unwrap()).collect();times.sort();let before=times.len();times.dedup();if times.len()!=before{duplicate_batches+=1;}}println!("duplicate timestamp batches: {duplicate_batches}/1000");}
